with measured as materialized(select @EXPRESSION@ as byte_count from (select a as audit_row from public.audit_events a limit 1000) s)
select pg_catalog.jsonb_build_object('version','QT_AUDIT_COST_CONSUMED_V1','mode',@MODE@,'sampleLimit',1000,'sampleCount',count(*)::text,'evaluatedCount',count(byte_count)::text,'bytesTotal',coalesce(sum(byte_count::bigint),0)::text,'database',current_database(),'backendPid',pg_backend_pid(),'holderPid',@PID@,'holderGranted',(@HELD@),'readOnly',current_setting('transaction_read_only')::boolean,'noRoleSwitch',current_user=session_user) as cost_counters from measured;